pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameter: an arbitrary caller address that may or may not be the deployer
    function testFuzz_property(address caller, address newOwner) public {
        // keep addresses in the admissible domain (non-zero newOwner helps avoid trivial no-op)
        vm.assume(newOwner != address(0));

        address deployer = address(this); // test contract deployed and created C, so this is owner

        // Attempt to have `caller` call transferOwnership(newOwner).
        // If caller == deployer, the correct contract allows ownership transfer; otherwise it must not.
        bool ok;
        // perform the external call as the fuzzed caller
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assertion): After the attempt, the owner is either unchanged (still deployer)
        // or the caller was the deployer who legitimately changed it. In other words:
        // assertTrue( c.owner() == deployer || (caller == deployer && c.owner() == newOwner) )
        // This reads only c's public getter. The mutant (which removes the require) permits a non-deployer
        // caller to change owner, causing this assertion to fail for some fuzzed caller/newOwner.
        assertTrue( c.owner() == deployer || (caller == deployer && c.owner() == newOwner) );
    }
}

