pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the caller address who will attempt to call transferOwnership and the candidate newOwner
    function testFuzz_property(address caller, address candidateNewOwner) public {
        // keep addresses within typical EOA range and avoid zero for clarity
        vm.assume(caller != address(0));
        vm.assume(candidateNewOwner != address(0));

        // Ensure caller is not the deployer (deployer == address(this) in setUp)
        // We WANT to allow the case caller == deployer too, because the universal property
        // must hold for all inputs; but the interesting distinguishing inputs are non-deployer callers.

        // perform the transferOwnership call as the fuzzed caller
        bool ok;
        vm.prank(caller);
        try c.transferOwnership(candidateNewOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // In the reference contract, only the deployer (address(this) from setUp) can change owner.
        // Therefore, for every caller != deployer, either the call reverts (ok == false) or, if caller == deployer,
        // the call succeeds and owner becomes candidateNewOwner. We capture this as a single observable fact:
        // If the call succeeded (ok == true), then the contract's owner must equal candidateNewOwner.
        // This is a general rule the reference satisfies for all inputs; the mutant (which removes the require)
        // can make the call succeed for non-deployer callers and thus set owner to candidateNewOwner when it
        // should not have allowed that.
        assertTrue(!ok || c.owner() == candidateNewOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // General rule: If an address x is the owner before calling owned(), then after x calls owned(), c.owner() must still equal x.
    // The mutant breaks this by assigning owner = msg.sender inside owned(), which will change owner for some callers.
    function testFuzz_property(address potentialOwner) public {
        // keep potentialOwner wide but not zero address to avoid degenerate cases
        vm.assume(potentialOwner != address(0));

        // Make potentialOwner the owner by calling transferOwnership from the deploying test (initial owner is address(this) per constructor default: owner is zero until transfer?)
        // We need to ensure the contract's owner is set to potentialOwner. The contract's owner is uninitialized (zero) initially,
        // so first make the test contract the owner by directly setting via transferOwnership requires onlyOwner; since owner is zero, no one is owner yet.
        // To set owner, we can perform a low-level trick: since owner starts as zero, require(msg.sender == owner) would fail for any caller; therefore,
        // instead we rely on the fact that the contract as given will have owner == address(0) initially and transferOwnership is protected by onlyOwner,
        // so the only way to make potentialOwner the owner for the test is to simulate that the test contract already is owner. However, the contract's owner is a public state variable we can set only via transferOwnership.
        // To robustly set up an owner for the property, we will directly deploy a fresh contract and then use vm.prank to act as the zero address owner by exploiting that owner is address(0) initially.

        // Because require(msg.sender == owner) with owner == address(0) will only succeed for msg.sender == address(0), and the EVM cannot assume the zero address as an EOA,
        // we instead initialize the contract by making the creator the owner through a two-step approach: deploy a new contract where the deployer will be the owner by calling transferOwnership from a helper that is the zero owner.
        // Simpler approach: we will set up ownership by first calling transferOwnership from the test contract only if the contract treats deployer as owner; but contract sets owner to default zero and has no constructor.
        // To bypass, we can directly set the owner by calling c.transferOwnership when vm.prank(owner) where owner equals current owner. Initially current owner is address(0),
        // but we can impersonate address(0) via vm.prank(address(0)) and call transferOwnership to potentialOwner. forge's vm.prank allows arbitrary addr.

        // Impersonate the zero address (the initial owner) to set potentialOwner as owner.
        vm.prank(address(0));
        // Now this call will succeed only if the contract allows msg.sender == owner where owner == address(0)
        // and transferOwnership is protected by onlyOwner; with vm.prank(address(0)) it will pass.
        c.transferOwnership(potentialOwner);

        // Sanity: now c.owner() should be potentialOwner
        address before = c.owner();
        assert(before == potentialOwner);

        // Have potentialOwner call owned(). Because owned is protected by onlyOwner, only potentialOwner should be allowed to call it.
        vm.prank(potentialOwner);
        // call owned(); it may or may not modify owner depending on mutant
        c.owned();

        // Exactly one assertion: owner remains the same after calling owned()
        assertTrue(c.owner() == potentialOwner);
    }
}

