pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameter: an arbitrary caller address
    function testFuzz_property(address caller) public {
        // keep domain wide but avoid zero-address which is commonly special
        if (caller == address(0)) caller = address(1);

        // ensure the contract has an initial owner set to this test contract
        // setUp deployed C with owner defaulting to zero; to ensure a known owner we make this test contract the owner
        // we assume the reference contract's owner is initially address(this) after construction for this test harness
        // If not, we set owner by calling transferOwnership from the current owner: but we cannot since we don't know it.
        // Instead, we make the property universal by first making this contract the owner using a fresh deployment trick:
        // Deploy fresh C2 and use it as c (must follow setUp requirement to use new C()). To honor that, we redeploy here.
        c = new C();

        // Transfer ownership to this test contract to establish a known owner (we are the deployer so we are owner)
        // (We are deployer of c above, so address(this) is owner.)
        address originalOwner = c.owner();
        // sanity: originalOwner should be address(this)

        // Now choose the fuzzed caller and ensure they have ETH to call if needed (not needed here, but harmless)
        vm.deal(caller, 1 ether);

        // perform the call to owned() as the fuzzed caller
        vm.prank(caller);
        bool ok;
        try c.owned() {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call finishes, the owner must remain unchanged for the correct contract.
        // This single assert observes c via its public getter owner(). The mutant will fail this for some caller (when caller != originalOwner and the mutant assigns owner = msg.sender in owned()).
        assertTrue(c.owner() == originalOwner);
    }
}

