pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameter: an address that will act as the owner and caller
    function testFuzz_property(address ownerAndCaller) public {
        // Keep domain wide but avoid the zero address because some contracts treat it specially
        vm.assume(ownerAndCaller != address(0));

        // Arrange: set the contract's owner to ownerAndCaller by calling transferOwnership as the current owner.
        // The contract's initial owner is address(0) (default). To set owner we need to be the owner first.
        // Since the contract has public `owner` and onlyOwner modifier, we simulate becoming owner by direct
        // construction: we rely on the deployer (this test contract) being able to call transferOwnership.
        // The deployer (this) is msg.sender for setUp deploy; however setUp deployed C with msg.sender = address(this),
